134	            /// Why we didn't use char* here?
135	            /// We don't know the size of the result string beforehand (it's not byte-to-byte encoding),
136	            /// so we may need to do many resizes (the worst case -- we'll do it for each row)
137	            /// This way we do exponential resizes and one final resize after whole operation is complete
138	            decoded.clear();
139	            if (srclen)
140	                try
141	                {
142	                    decoder.decode(decoded, source, srclen);
143	                }
