203	    DataTypePtr getReturnTypeImpl(const ColumnsWithTypeAndName & arguments) const override
204	    {
205	        if (arguments.size() != 1 && arguments.size() != 2)
206	            throw Exception(
207	                "Wrong number of arguments for function " + getName() + ":  1 or 2 expected.",
208	                ErrorCodes::BAD_ARGUMENTS);
209	
210	        if (!isString(arguments[0].type))
211	            throw Exception(
212	                "Illegal type " + arguments[0].type->getName() + " of 1st argument of function " + getName() + ". Must be String.",
213	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
214	
215	        if (arguments.size() == 2 && !isString(arguments[1].type))
216	            throw Exception(
217	                "Illegal type " + arguments[1].type->getName() + " of 2nd argument of function " + getName() + ". Must be String.",
218	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
219	
220	        return std::make_shared<DataTypeString>();
221	    }
222	
223	    ColumnPtr executeImpl(const ColumnsWithTypeAndName & arguments, const DataTypePtr &, size_t input_rows_count) const override
224	    {
